parameters.jsCode:
const job = $('Loop Over Items').item.json;
const check = $('Checks_Relevance').item.json.output || {};
const raw = typeof $json.text === 'string' ? $json.text
          : (typeof $json.output === 'string' ? $json.output : '');
const cv = (raw.split('===CV===')[1] || '').split('===LETTER===')[0]
  .replace(/```(latex|tex)?/g, '').trim();
const letter = (raw.split('===LETTER===')[1] || '').trim();

return { json: {
  relevant: check.relevant ?? false,
  score: check.score ?? 0,
  reason: check.reason ?? '',
  title: job.title,
  company: job.companyName,
  location: job.location,
  postedAt: job.postedAt,
  link: job.link,
  applyUrl: job.applyUrl,
  applicants: job.applicantsCount,
  seniority: job.seniorityLevel,
  description: String(job.descriptionText || '').slice(0, 5000),
  tailored_cv_tex: cv,
  cover_letter: letter
}};
